import createClient from "openapi-fetch";
import { PUBLIC_GO_BACKEND_URL } from "$env/static/public";
import { getLocale } from "$paraglide/runtime";
import type { paths } from "./schema";

/**
 * Generated typed client for the Go backend (../../../api). Types come
 * from schema.d.ts (generated by `openapi-typescript` from the Go API's
 * own OpenAPI spec by `pnpm generate:api`). Call it directly at call sites, e.g.
 * `api.GET("/articles/{slug}", { params: { path: { slug } } })` - no
 * hand-written wrapper functions per endpoint.
 *
 * Lives outside $lib/server because SvelteKit's universal `+page.ts` loads
 * call this API directly from the browser as well as the server - a
 * `$lib/server` module
 * cannot be imported from code that also runs client-side.
 *
 * `credentials: "include"` below only matters for a real browser fetch -
 * the browser's own cookie jar attaches the session cookie and stores any
 * Set-Cookie response automatically, no code needed. It does nothing when
 * this same call executes inside the Node process itself (SSR of a
 * `+page.ts`, or any `+page.server.ts` load/action) - there's no browser
 * involved in a server-to-server request, so nothing forwards cookies
 * either direction on its own (same reason goAuth.ts's fetchIdentity()
 * has always forwarded /me's cookies by hand). `+page.server.ts` files
 * use `$lib/server/apiClient`'s `serverApi(event)` instead, which
 * forwards cookies explicitly. A `+page.ts` load can't do that (no
 * server-only imports, no raw cookie access) - every call site here
 * already passes its own `fetch` parameter into each `api.*()` call
 * (`api.GET(..., { fetch })`), which is the correct, established
 * pattern: it lets SvelteKit's built-in same-site cookie passthrough
 * apply during SSR, best-effort. Keep doing this for any new `+page.ts`
 * call site - it's free and can only help, even though it isn't a
 * complete guarantee: SvelteKit only forwards cookies to a subdomain of
 * its own host, and never passes a cross-origin Set-Cookie back.
 */
export const api = createClient<paths>({
  baseUrl: PUBLIC_GO_BACKEND_URL,
  // The session cookie (apps/api/internal/auth) must ride along on every
  // request now that real auth exists - the backend's CORS layer
  // (internal/api.withCORS) only allows this because it echoes this site's
  // own origin rather than "*" (browsers reject that combination for
  // credentialed requests).
  credentials: "include",
});

// The Go API resolves translated fields from Accept-Language (see
// apps/api/internal/locale) - send the site's actual selected locale
// (paraglide's getLocale(), which can differ from the browser's own
// language settings if the user picked a language via the site's own
// switcher) rather than leaving the browser's default header in place.
api.use({
  onRequest({ request }) {
    request.headers.set("Accept-Language", getLocale());
    return request;
  },
});

/**
 * Request options for a multipart (file upload) endpoint: pass the body as
 * a plain object, typed by the generated schema, and it is sent as
 * FormData. Arrays become repeated fields.
 *
 *   api.POST("/images", { body: { file }, ...multipart })
 */
export const multipart = {
  bodySerializer(body: object | undefined) {
    const form = new FormData();
    for (const [key, value] of Object.entries(body ?? {})) {
      for (const item of Array.isArray(value) ? value : [value]) {
        if (item === undefined || item === null) continue;
        form.append(key, item instanceof Blob ? item : String(item));
      }
    }
    return form;
  },
};
